#pragma once
static const char PS4HDDTOOLS_INDEX_HTML[] = R"PS4HTML(
<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ps4hddtools</title>
<style>
:root{color-scheme:light dark;--bg:#f2f4f8;--panel:#fff;--text:#1e2430;--muted:#697386;--border:#d9dee8;--accent:#2674df;--good:#39a96b;--bad:#e24b4b;--unknown:#b9c1ce;--tile:#e3e8ef}
@media(prefers-color-scheme:dark){:root{--bg:#11151c;--panel:#1a202a;--text:#e8edf5;--muted:#9ca8ba;--border:#303a49;--accent:#65a4ff;--good:#42c77a;--bad:#ff5d66;--unknown:#596576;--tile:#293342}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,Segoe UI,sans-serif}header{display:flex;align-items:center;justify-content:space-between;padding:16px 22px;background:var(--panel);border-bottom:1px solid var(--border)}h1{font-size:20px;margin:0}main{padding:18px;display:grid;grid-template-columns:290px minmax(0,1fr);gap:16px}.panel{background:var(--panel);border:1px solid var(--border);border-radius:12px;padding:16px;min-width:0}.muted{color:var(--muted)}.disk{padding:12px;border:1px solid var(--border);border-radius:9px;margin-top:8px;cursor:pointer}.disk.selected{border-color:var(--accent);box-shadow:inset 3px 0 var(--accent)}.disk strong{display:block}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:14px 0}.stat{background:var(--bg);border:1px solid var(--border);border-radius:9px;padding:12px;min-width:0}.stat label{display:block;color:var(--muted);font-size:12px}.stat b{display:block;margin-top:5px;overflow-wrap:anywhere;font-size:16px}button{border:0;border-radius:8px;padding:10px 16px;background:var(--accent);color:white;font-weight:650;cursor:pointer}button.secondary{background:var(--tile);color:var(--text)}button.danger{background:#bd3e48}button:disabled{opacity:.45;cursor:not-allowed}.map{display:grid;grid-template-columns:repeat(25,minmax(4px,1fr));gap:3px;margin-top:12px}.cell{height:17px;border-radius:3px;background:var(--unknown)}.cell.good{background:var(--good)}.cell.bad{background:var(--bad)}.legend{display:flex;gap:14px;flex-wrap:wrap;margin-top:12px;color:var(--muted);font-size:12px}.dot{display:inline-block;width:9px;height:9px;border-radius:2px;margin-right:5px;background:var(--unknown)}.dot.good{background:var(--good)}.dot.bad{background:var(--bad)}.bar{height:9px;background:var(--tile);border-radius:9px;overflow:hidden}.bar span{display:block;height:100%;width:0;background:var(--accent);transition:width .25s}.status{margin:12px 0;color:var(--muted)}@media(max-width:850px){main{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:420px){header{padding:12px}main{padding:10px}.panel{padding:12px}.map{gap:2px}.cell{height:12px}}
</style></head><body>
<header><h1>ps4hddtools</h1><span class="muted">PS4 · HDD / SSD</span></header>
<main><aside class="panel"><h2>Накопители</h2><p class="muted">Подключённые диски и устройства</p><div id="disks">Поиск устройств…</div><button class="secondary" style="margin-top:12px" onclick="loadDisks()">Обновить список</button></aside>
<section class="panel"><div class="row" style="justify-content:space-between"><div><h2 style="margin:0">Проверка поверхности</h2><div class="muted" id="selected">Выберите диск слева</div></div><span id="state" class="muted">Ожидание</span></div>
<div class="stats"><div class="stat"><label>Прогресс</label><b id="percent">0%</b></div><div class="stat"><label>Скорость чтения</label><b id="speed">—</b></div><div class="stat"><label>Осталось</label><b id="eta">—</b></div><div class="stat"><label>Ошибки чтения</label><b id="errors">0</b></div></div>
<div class="bar"><span id="progress"></span></div><div id="message" class="status">Перед стартом будет выполнен замер доступного диска и рассчитано ориентировочное время.</div>
<div class="row"><button id="start" onclick="startScan()">Пуск</button><button class="secondary" onclick="post('/api/scan/pause')">Пауза</button><button class="secondary" onclick="post('/api/scan/resume')">Продолжить</button><button class="danger" onclick="post('/api/scan/stop')">Стоп</button></div>
<h3>Карта блоков</h3><div class="muted">Зелёный — прочитан; красный — ошибка чтения; серый — ещё не проверен.</div><div id="map" class="map"></div><div class="legend"><span><i class="dot good"></i>Успешное чтение</span><span><i class="dot bad"></i>Ошибка чтения</span><span><i class="dot"></i>Не проверен</span></div>
</section></main>
<script>
let selected='';const $=id=>document.getElementById(id);
function fmtBytes(n){if(!n)return 'Размер неизвестен';let u=['Б','КиБ','МиБ','ГиБ','ТиБ'],i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return n.toFixed(i?1:0)+' '+u[i]}
function fmtTime(n){if(n<0||!Number.isFinite(n))return 'Расчёт…';let h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=Math.floor(n%60);return (h? h+' ч ':'')+(m+' мин '+s+' с')}
async function loadDisks(){try{let d=await(await fetch('/api/disks')).json();$('disks').innerHTML='';if(!d.disks.length)$('disks').textContent='Устройства не найдены';d.disks.forEach(x=>{let el=document.createElement('div');el.className='disk'+(selected===x.path?' selected':'');el.innerHTML='<strong></strong><span class="muted"></span>';el.firstChild.textContent=x.name;el.lastChild.textContent=x.path+' · '+fmtBytes(x.bytes);el.onclick=()=>{selected=x.path;loadDisks();$('selected').textContent=x.path+' · '+fmtBytes(x.bytes)};$('disks').appendChild(el)})}catch(e){$('disks').textContent='Ошибка API: '+e}}
async function post(url,body={}){try{let r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});let j=await r.json();if(!r.ok)alert(j.error||'Ошибка запроса');poll()}catch(e){alert('Нет связи с сервисом')}}
async function startScan(){if(!selected){alert('Сначала выберите диск');return}if(!confirm('Запустить полное чтение поверхности '+selected+'? Проверка только читает данные и может занять много часов.'))return;post('/api/scan/start',{device:selected})}
function drawMap(a){let map=$('map');if(map.children.length!==a.length){map.innerHTML='';a.forEach(()=>{let e=document.createElement('i');e.className='cell';map.appendChild(e)})}a.forEach((v,i)=>map.children[i].className='cell '+(v===1?'good':v===2?'bad':''))}
async function poll(){try{let s=await(await fetch('/api/status')).json();$('state').textContent=s.state;$('selected').textContent=s.device|| (selected||'Выберите диск слева');$('percent').textContent=s.percent.toFixed(1)+'%';$('progress').style.width=s.percent+'%';$('speed').textContent=s.speed_bps?(s.speed_bps/1e6).toFixed(1)+' МБ/с':'—';$('eta').textContent=fmtTime(s.eta_seconds);$('errors').textContent=s.read_errors;$('message').textContent=s.message;drawMap(s.block_map||[])}catch(e){$('message').textContent='Не удалось получить состояние API'}}
loadDisks();poll();setInterval(poll,1000);setInterval(loadDisks,10000);
</script></body></html>
)PS4HTML";
